async function handleTurn(userMessage, session) {
  const plan = await model.decide({
    message: userMessage,
    tools: [orderServer.tools, kbServer.tools, emailServer.tools].flat(),
    history: session.history,
  });

  for (const call of plan.toolCalls) {
    const server = routeToServer(call.name); // order, kb, or email
    if (server.risky(call)) {
      await requestHumanApproval(call, session);
      continue; // resumes only after approval, does not block other calls
    }
    const result = await server.invoke(call, { callerId: session.userId });
    session.recordToolResult(call.name, result);
  }

  return model.composeReply(session);
}

function isRisky(toolCall) {
  return toolCall.server === "email" && toolCall.name === "send_reply";
}

if (isRisky(call)) {
  const approved = await humanApprovalQueue.waitFor(call, { timeoutMs: 900000 });
  if (!approved) return session.recordToolResult(call.name, { status: "denied" });
}
